/** A client that answers `{ n }`, n counting its calls, or what `answer` says; and the calls it was asked. */
const counting = (answer?: (n: number, request: HttpRequest) => unknown) => {
  const calls: Array<{ path: string, request: HttpRequest }> = []
  const call: HttpClient = async (path, request) => {
    calls.push({ path, request })
    return answer ? answer(calls.length, request) : { n: calls.length }
  }
  return { call, calls }
}

